            "1 paquete de tortillas mexicanas",
            "1 aguacate",
            "1 tomate",
            "1 cebolla",
            "Lechuga",
            "1 limón",
            "Salsa BBQ",
            "1/4 de pimiento rojo",
            "1 chorro de mayonesa",
            "Sal",
            "Pimienta",
            "Ají molido",
            "Curry",
            "Salsa de soya",
            "Ajo",
