        "titulo": "Receta de Lasaña de pollo y carne molida",
        "categoria": "Comida Italiana",
        "tiempo": "2h 30m",
        "imagen": "https://cdn0.recetasgratis.net/es/posts/5/7/7/lasana_de_pollo_y_carne_molida_57775_orig.jpg",
